  "tools": [
    {
      "type": "function",
      "description": "Propose ONE change to the model. This does NOT change anything: it records an exact proposal and returns its id, which you keep for authorise_change: show the user what it changes, never the id, before asking them to approve. Use the labels exactly as get_canonical_state returned them. On a host-bound drawn_link press ONLY, propose your own band, direction and one-line reason for that exact pair, shown as Olumi\u2019s estimate. For every other turn, the link is recorded with `strength` as the user\u2019s own estimate, so give ONLY the band the user named for it in this message; if they described it in their own words (\"very high\"), give your reading in `strength` and their exact phrase in `from_words`, and show it; if they named none, ask how strong the effect is first \u2014 a band they did not say is refused. The canvas calls the lowest band Slight: when the user calls a link slight, that IS `weak` \u2014 pass `weak`, and never ask whether slight means weak. When you ask the user for a band, use the canvas\u2019s words: slight, moderate, strong or very strong.",
      "name": "propose_model_change",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "from_label": {
            "type": "string"
          },
          "to_label": {
            "type": "string"
          },
          "direction": {
            "type": "string",
            "enum": [
              "positive",
              "negative"
            ]
          },
          "strength": {
            "type": "string",
            "enum": [
              "weak",
              "moderate",
              "strong",
              "very strong"
            ],
            "description": "The band the user said for this link in THIS message, in their own words \u2014 or your reading of their own words, given with `from_words`. Only for the host-bound drawn_link pair, your own Olumi estimate is allowed."
          },
          "reason": {
            "type": "string",
            "maxLength": 140,
            "description": "For a host-bound drawn link: one short plain line explaining your estimate, with no figures."
          },
          "from_words": {
            "type": "string",
            "description": "When the user described the strength in their own words rather than a band word, give their exact phrase here and your reading in `strength`; the user approves your reading. Copy it exactly from their message this turn (for example \"very high\"); never a phrase they did not write."
          },
          "rationale": {
            "type": "string",
            "description": "Why this link matters, in the user\u2019s terms."
          }
        },
        "required": [
          "from_label",
          "to_label",
          "direction",
          "strength",
          "reason",
          "from_words",
          "rationale"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Apply a previously returned proposal. Call this ONLY after the user has explicitly approved that specific proposal in their own words. The stored proposal is applied \u2014 nothing is regenerated. Report exactly what the result says, including a refusal.",
      "name": "authorise_change",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "proposal_id": {
            "type": "string"
          }
        },
        "required": [
          "proposal_id"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Withdraw a change you proposed earlier in THIS turn that you now think is wrong, before you reply. It is never applied and no approve button is shown. Never ask the user not to approve a change you leave offered. An unresolved goal reading (goal-scope: ID) may also be withdrawn, but only when the user writes exactly \"Withdraw this unresolved goal reading: <goal_id>\". Otherwise retain its question.",
      "name": "withdraw_proposal",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "proposal_id": {
            "type": "string"
          }
        },
        "required": [
          "proposal_id"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Run the decision analysis over the persisted model. It may refuse and explain what is missing; report that honestly rather than guessing what the result would have been.",
      "name": "run_analysis",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "reason": {
            "type": "string"
          }
        },
        "required": [
          "reason"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Build the decision model from the user\u2019s brief when get_canonical_state reports the model is empty. Preserves the user\u2019s own facts, numbers and constraint wording, then adds the options, factors, risks and causal mechanisms that make the decision reasonable to analyse. Report honestly what it says was left out.",
      "name": "build_model_from_brief",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "brief": {
            "type": "string",
            "description": "The user\u2019s decision in their own words, verbatim."
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "brief",
          "whole_request"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Propose starting values for factors that have none, so the model can be reasoned about instead of sitting blank. This does NOT change anything: it records an exact proposal and returns its id, which you keep for authorise_change: show the user the values, never the id, before asking them to approve. Each value is an assumption for the user to adopt or correct, NEVER a measurement \u2014 say so; a value the result marks `your_figure` is the user\u2019s own figure, never called an assumption. Propose only factors the model actually has, using the labels get_canonical_state returned. A factor that already holds a value is left alone UNLESS you set `revise: true` on it, which you may do ONLY when the user has just asked for that factor to be changed and named the number themselves. Never set it to replace someone\u2019s figure with one of your own. When the user asks to revise an existing value without supplying a replacement figure, ask what figure they would use; never supply a number or an instruction for them to repeat as their own. When the user says Olumi\u2019s current estimate for a factor is right and should stay, set `keep: true` on it instead: nothing changes, and their approval records that they accepted Olumi\u2019s estimate.",
      "name": "propose_assumptions",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "assumptions": {
            "type": "array",
            "description": "The factors to give a starting value, with the reasoning for each.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "factor_label": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                },
                "unit": {
                  "type": "string"
                },
                "basis": {
                  "type": "string",
                  "description": "Why this is a reasonable starting point, in the user\u2019s terms."
                },
                "revise": {
                  "type": "boolean",
                  "description": "Set true ONLY when the user has just asked for this factor to be changed and gave the number. It permits replacing a value that is already there; the approval will show the user both the current value and the new one. Omit it in every other case."
                },
                "keep": {
                  "type": "boolean",
                  "description": "Set true ONLY when the user has just said Olumi\u2019s CURRENT figure for this factor is right and should stay. The stored figure is kept exactly (give it as value); it stays Olumi\u2019s estimate and the approval records that the user accepted it. Never on the user\u2019s own figure or one from their brief, never with a different number, and never in the same call as other values. Omit it in every other case."
                }
              },
              "required": [
                "factor_label",
                "value",
                "unit",
                "basis",
                "revise",
                "keep"
              ]
            }
          }
        },
        "required": [
          "assumptions"
        ]
      },
      "strict": true
    },
    {
      "type": "function",
      "description": "Add an option the user has just asked for. If its exact label already identifies a stored option marked `proposed_by: olumi`, call this tool with that label and no edits to offer adoption of the SAME option into their comparison. Its Olumi origin and suggested levels remain labelled as Olumi's; do not call it an existing user option or a user-stated figure. This does NOT change anything: it prepares ONE complete change and returns its id, which you keep for authorise_change: show the user the option and what it will be linked to, never the id, before asking them to approve. The option is linked from the decision automatically. Name the factors it would change, using the labels get_canonical_state returned. Give a level for a figure the user stated, in their own units; for an option YOU suggested you may give your own suggested figure with estimate: true and a basis, recorded and shown as Olumi\u2019s estimate. Never a placeholder. A factor with no level is added with no level, and you say plainly what is still needed. When the user asks for SEVERAL options (up to 4), put them ALL in `options` in ONE call: they become ONE change the user approves once, and it lands whole or not at all. If an option changes something the model has NO factor for, add that factor in the SAME change with `new_factors` (never link the option to an unrelated factor instead), and name it in `acts_on`. Only for something the user asked the option to change; what it changes and which way come from the user\u2019s words, or where it is plain from the option itself (a paid add-on adds revenue); if it is unclear, ask. Once a call has prepared a change, never call it again in the same reply. A call that was REFUSED prepared nothing: you may call it once more in the same reply, corrected as the refusal says.",
      "name": "propose_new_option",
      "output_schema": null,
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "label": {
            "type": "string",
            "description": "ONE option in the user\u2019s own words. For several, use `options` instead."
          },
          "acts_on": {
            "type": "array",
            "description": "The factors this option would change, and which way. At least one.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "factor_label": {
                  "type": "string"
                },
                "direction": {
                  "type": "string",
                  "enum": [
                    "positive",
                    "negative"
                  ],
                  "description": "Whether this option pushes the factor up or down. State it; never guess it for the user."
                },
                "level": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "value": {
                      "type": "number",
                      "description": "The figure the user stated FOR THIS FACTOR, in the factor\u2019s own units (e.g. 54 for \u00a354 on a price). A figure given for something else (a price, when this factor is a churn rate) is never this factor\u2019s level: leave level out. With no figure from the user, leave level out \u2014 never 0 or any placeholder to mean \u201cnot set\u201d \u2014 unless it is your OWN suggested figure for an option you suggested: then set estimate."
                    },
                    "unit": {
                      "type": "string",
                      "description": "The unit the user stated, if any."
                    },
                    "estimate": {
                      "type": "boolean",
                      "description": "true ONLY when this figure is your own suggestion, not the user\u2019s (an option you proposed, at the figure you proposed). It is recorded and shown as Olumi\u2019s estimate, never as the user\u2019s. Needs basis."
                    },
                    "basis": {
                      "type": "string",
                      "description": "With estimate: why this figure, in plain words the user can check."
                    }
                  },
                  "required": [
                    "value",
                    "unit",
                    "estimate",
                    "basis"
                  ],
                  "description": "The level this option sets the factor to. Never give a level for a factor you add in new_factors with kind 'switch': a switch has no level of its own \u2014 the option turns it on."
                }
              },
              "required": [
                "factor_label",
                "direction",
                "level"
              ]
            }
          },
          "options": {
            "type": "array",
            "description": "Several options the user asked for (2 to 4), each with its own label and factors. One change, one approval.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "label": {
                  "type": "string",
                  "description": "The option in the user\u2019s own words."
                },
                "acts_on": {
                  "type": "array",
                  "description": "The factors this option would change, and which way. At least one.",
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "factor_label": {
                        "type": "string"
                      },
                      "direction": {
                        "type": "string",
                        "enum": [
                          "positive",
                          "negative"
                        ],
                        "description": "Whether this option pushes the factor up or down. State it; never guess it for the user."
                      },
                      "level": {
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                          "value": {
                            "type": "number",
                            "description": "The figure the user stated FOR THIS FACTOR, in the factor\u2019s own units (e.g. 54 for \u00a354 on a price). A figure given for something else (a price, when this factor is a churn rate) is never this factor\u2019s level: leave level out. With no figure from the user, leave level out \u2014 never 0 or any placeholder to mean \u201cnot set\u201d \u2014 unless it is your OWN suggested figure for an option you suggested: then set estimate."
                          },
                          "unit": {
                            "type": "string",
                            "description": "The unit the user stated, if any."
                          },
                          "estimate": {
                            "type": "boolean",
                            "description": "true ONLY when this figure is your own suggestion, not the user\u2019s (an option you proposed, at the figure you proposed). It is recorded and shown as Olumi\u2019s estimate, never as the user\u2019s. Needs basis."
                          },
                          "basis": {
                            "type": "string",
                            "description": "With estimate: why this figure, in plain words the user can check."
                          }
                        },
                        "required": [
                          "value",
                          "unit",
                          "estimate",
                          "basis"
                        ],
                        "description": "The level this option sets the factor to. Never give a level for a factor you add in new_factors with kind 'switch': a switch has no level of its own \u2014 the option turns it on."
                      }
                    },
                    "required": [
                      "factor_label",
                      "direction",
                      "level"
                    ]
                  }
                }
              },
              "required": [
                "label",
                "acts_on"
              ]
            }
          },
          "new_factors": {
            "type": "array",
            "description": "Factors the model does NOT have that these options change, added in this same change. Each is named in an option\u2019s acts_on.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "label": {
                  "type": "string",
                  "description": "The factor in the user\u2019s words (e.g. \"AI add-on price\")."
                },
                "affects": {
                  "type": "array",
                  "description": "What this factor changes that the model already has (the goal, an outcome, a risk, or a factor no option sets), and which way. At least one.",
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "label": {
                        "type": "string",
                        "description": "A label exactly as get_canonical_state gives it."
                      },
                      "direction": {
                        "type": "string",
                        "enum": [
                          "positive",
                          "negative"
                        ],
                        "description": "Whether raising this factor raises (positive) or lowers (negative) it: from the user\u2019s words, or where it is plain from the option itself (a paid add-on adds revenue); if it is unclear, ask. The preview names it so the user can correct it."
                      }
                    },
                    "required": [
                      "label",
                      "direction"
                    ]
                  }
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "switch",
                    "graded"
                  ],
                  "description": "\"switch\" when the option simply turns this ON \u2014 something not in place today that the option puts in place (grandfathering existing customers, launching a feature). It is then added as off today, Olumi\u2019s reading for the user to correct, and on under every option that acts on it: give it no level. Leave kind out for an amount or a rate (a price, a share of customers): its current value is `today` when the user stated it, otherwise asked for, and the option\u2019s level is asked for."
                },
                "today": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "value": {
                      "type": "number",
                      "description": "The figure the user stated for this factor TODAY, in their own units (e.g. 49 for \u201cfrom \u00a349 to \u00a359\u201d on a price)."
                    },
                    "unit": {
                      "type": "string",
                      "description": "The unit the user stated it in."
                    }
                  },
                  "required": [
                    "value",
                    "unit"
                  ],
                  "description": "For a factor you add, give today\u2019s level ONLY if the user stated it in their own words (e.g. a price they said moves \"from \u00a349\" is \u00a349 today). Never your own estimate, never a placeholder or 0: with no figure from the user, leave today out and ask for it. Never for a switch."
                }
              },
              "required": [
                "label",
                "affects",
                "kind",
                "today"
              ]
            }
          },
          "rationale": {
            "type": "string",
            "description": "Why this option is worth comparing, in the user\u2019s terms."
          },
          "whole_request": {
            "type": "boolean",
            "description": "true ONLY when this one call does everything the user asked for in their latest message: no other change to make, no question to answer, nothing else to explain. If there is anything more, or you are unsure, false."
          }
        },
        "required": [
          "label",
          "acts_on",
          "options",
          "new_factors",
          "rationale",
          "whole_request"
        ]
      },
      "strict": true
    },
